#!/usr/bin/env node
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {spawnSync} from 'node:child_process';

const root=path.resolve(import.meta.dirname,'..');
const read=relative=>fs.readFileSync(path.join(root,relative),'utf8');
const rustFiles=[];
const walk=directory=>{
  for(const entry of fs.readdirSync(directory,{withFileTypes:true})){
    const absolute=path.join(directory,entry.name);
    if(entry.isDirectory())walk(absolute);
    else if(entry.isFile()&&entry.name.endsWith('.rs'))rustFiles.push(absolute);
  }
};
walk(path.join(root,'src-tauri','src'));
walk(path.join(root,'src-tauri','crates'));
rustFiles.sort();
assert.ok(rustFiles.length>=40,'Rust source inventory is unexpectedly incomplete');

let syncSites=0;
for(const file of rustFiles){
  const source=fs.readFileSync(file,'utf8');
  const relative=path.relative(root,file).split(path.sep).join('/');
  assert.ok(!/\.and_then\(\|file\|\s*file\.sync_all\(\)\)/s.test(source),`${relative}: read-only Windows fsync regression returned`);
  syncSites+=(source.match(/\.sync_all\(\)/g)??[]).length;
}

const durable=read('src-tauri/src/transactional_core/durable_fs.rs');
for(const marker of ['.read(true)','.write(true)','rename_atomic','WINDOWS_RENAME_ATTEMPTS','Some(5) | Some(32) | Some(33)','existing_file_is_flushed_without_truncation','atomic_rename_publishes_exact_contents']){
  assert.ok(durable.includes(marker),`durable_fs.rs is missing ${marker}`);
}
assert.ok(durable.indexOf('.write(true)')<durable.indexOf('sync_all()'),'durable fsync handle is not write-capable');
assert.ok(!durable.includes('.truncate(true)')&&!durable.includes('.create(true)'),'durable fsync helper can mutate an existing file');

for(const relative of ['src-tauri/src/transactional_core/backup.rs','src-tauri/src/transactional_core/migrations.rs']){
  const source=read(relative);
  for(const marker of ['durable_fs::sync_file','durable_fs::rename_atomic','.close()'])assert.ok(source.includes(marker),`${relative} is missing ${marker}`);
}
const backup=read('src-tauri/src/transactional_core/backup.rs');
assert.ok(backup.indexOf('.close()')<backup.indexOf('durable_fs::sync_file(&partial_path)'),'backup file can be flushed before SQLite closes it');
const migrations=read('src-tauri/src/transactional_core/migrations.rs');
assert.ok(migrations.indexOf('.close()')<migrations.indexOf('durable_fs::sync_file(&partial)'),'migration backup can be flushed before SQLite closes it');

const assembly=read('src-tauri/src/lib.rs');
for(const marker of ['whoami.exe','/user','parse_windows_sid','format!("*{sid}")','*S-1-5-18','windowless_windows_command','CREATE_NO_WINDOW'])assert.ok(assembly.includes(marker),`Windows ACL path is missing ${marker}`);
assert.ok(!assembly.includes('std::env::var("USERNAME")')&&!assembly.includes('std::env::var("USERDOMAIN")'),'Windows ACL trusts locale/account-name environment variables');
for(const marker of ['window.show()','window.is_visible()','EngineClient::initialize_background','DesktopSmoke::from_process_args','DESKTOP_WINDOW_READY_TIMEOUT','app.manage(lease)'])assert.ok(assembly.includes(marker),`desktop startup recovery is missing ${marker}`);
assert.ok(assembly.indexOf('InstanceLease::acquire()')<assembly.indexOf('tauri::Builder::default()'),'a duplicate launch can create a second WebView before deciding instance ownership');
assert.ok(assembly.includes('run_desktop(smoke, lease)'),'the pre-window instance lease is not passed to Tauri setup');
assert.ok(!/\.manage\(lease\)[\s\S]*?\.setup\(/.test(assembly),'desktop lease returned to the pre-window Tauri builder chain');
const desktopStartup=read('src-tauri/src/desktop_startup.rs');
for(const marker of ['--desktop-startup-smoke','DESKTOP_BINARY_IDENTITY_MISMATCH','DESKTOP_WINDOW_READY','desktop-startup.log','MessageBoxW','create_new(true)'])assert.ok(desktopStartup.includes(marker),`desktop startup diagnostics are missing ${marker}`);
const engineClient=read('src-tauri/src/engine_client.rs');
for(const marker of ['initialize_background','CREATE_NO_WINDOW','HEADLESS_ENGINE_START_FAILED','STARTUP_ATTEMPTS'])assert.ok(engineClient.includes(marker),`background engine launch is missing ${marker}`);
const engineLease=read('src-tauri/src/transactional_core/engine_lease.rs');
for(const marker of ['PRODUCTION_MUTEX_NAME','TEST_MUTEX_PREFIX','platform::acquire(&file, &path)','fs::canonicalize(path)','test-isolated'])assert.ok(engineLease.includes(marker),`Windows engine lease test isolation is missing ${marker}`);
assert.ok(engineLease.includes('#[cfg(not(test))]')&&engineLease.includes('#[cfg(test)]'),'production and test engine mutex namespaces are not compile-time separated');
const instanceLease=read('src-tauri/src/transactional_core/instance_lease.rs');
for(const marker of ['FOCUS_ACK','INSTANCE_RUNNING_WITHOUT_READY_WINDOW','read_focus_ack','write_all(FOCUS_ACK)','signal_existing_until_ready','run_on_main_thread','FOCUS_READY_TIMEOUT','owner_present','AllowSetForegroundWindow','hello_busy.load'])assert.ok(instanceLease.includes(marker),`desktop focus readiness handshake is missing ${marker}`);
const daemonMain=read('src-tauri/src/bin/klipper-farmd.rs');
assert.ok(daemonMain.includes('windows_subsystem = "windows"'),'klipper-farmd would open a visible Windows console');
const ipcProbeMain=read('src-tauri/src/bin/klipper-farm-ipc-probe.rs');
assert.ok(ipcProbeMain.includes('run_ipc_probe_from_args(std::env::args_os())'),'native Windows IPC probe bypasses the production AF_UNIX client path');
const tauriConfig=JSON.parse(read('src-tauri/tauri.conf.json'));
assert.equal(tauriConfig.bundle.windows.nsis.installerHooks,'windows/installer-hooks.nsh','NSIS upgrade does not install the process-stop hook');
for(const relative of ['src-tauri/tauri.conf.json','src-tauri/tauri.offline.conf.json','src-tauri/tauri.release.conf.json'])assert.equal(JSON.parse(read(relative)).mainBinaryName,'klipper-farm-client',`${relative} does not pin the GUI main binary`);
const cargoManifest=read('src-tauri/Cargo.toml');
for(const marker of ['default-run="klipper-farm-client"','name="klipper-farm-client"','path="src/main.rs"','name="klipper-farmd"','path="src/bin/klipper-farmd.rs"','name="klipper-farm-ipc-probe"','path="src/bin/klipper-farm-ipc-probe.rs"'])assert.ok(cargoManifest.includes(marker),`Cargo binary identity is missing ${marker}`);
const installerHooks=read('src-tauri/windows/installer-hooks.nsh');
for(const marker of ['NSIS_HOOK_PREINSTALL','NSIS_HOOK_POSTINSTALL','NSIS_HOOK_PREUNINSTALL','klipper-farmd.exe','klipper-farm-client.exe','taskkill.exe','WriteRegStr SHCTX "${UNINSTKEY}" "MainBinaryName" "${MAINBINARYNAME}.exe"','CreateShortcut "$SMPROGRAMS\\${PRODUCTNAME}.lnk" "$INSTDIR\\${MAINBINARYNAME}.exe"'])assert.ok(installerHooks.includes(marker),`NSIS process/shortcut recovery hook is missing ${marker}`);
const libTests=read('src-tauri/src/lib_tests.rs');
assert.ok(libTests.includes('windows_sid_parser_accepts_unicode_account_names_without_trusting_them'),'Unicode Windows account/SID regression test is missing');

for(const relative of ['src-tauri/src/transactional_core/backup.rs','src-tauri/src/transactional_core/database_writer.rs','src-tauri/src/transactional_core/journal.rs','src-tauri/src/transactional_core/workflow.rs']){
  assert.ok(read(relative).includes('drop('),`${relative} does not close Windows test handles before cleanup`);
}

const runner=read('scripts/run-rust-tests.mjs');
for(const marker of ["['clean','-p','klipper-farm-client'","MIN_ROOT_TEST_COUNT=process.platform==='win32'?129:127",'--list','--test-threads=1','check-windows-test-loader.mjs','RELEASE-BUILD-ID.txt'])assert.ok(runner.includes(marker),`Rust test runner is missing ${marker}`);
const headless=read('src-tauri/src/headless_engine.rs');
for(const marker of ['resolve_socket_path','MAX_SOCKET_PATH_BYTES','LOCALAPPDATA','XDG_RUNTIME_DIR','long_data_directory_uses_a_short_private_socket_path','IPC_SOCKET_PATH_UNAVAILABLE','run_ipc_probe_from_args','call_published_endpoint','ipc_probe_schema_is_strict_and_never_accepts_a_caller_token','retire_stale_endpoint_after_lease','crash_left_endpoint_is_retired_before_rebinding_the_socket','runtime-restart-actor','actorsBootstrapped'])assert.ok(headless.includes(marker),`headless IPC path hardening is missing ${marker}`);
const headlessBootstrap=headless.slice(headless.indexOf('async fn run_server'),headless.indexOf('fn handle_connection'));
assert.ok(headlessBootstrap.indexOf('retire_stale_endpoint_after_lease')<headlessBootstrap.indexOf('LocalListener::bind'),'replacement daemon can self-probe a crash-left endpoint before its accept loop starts');
const launcher=read('FIX_AND_INSTALL.bat');
const installer=read('scripts/build-and-install-windows.mjs');
assert.ok(launcher.includes('scripts\\build-and-install-windows.mjs'),'Windows launcher bypasses the clean orchestrator');
for(const marker of ['RELEASE-BUILD-ID.txt','prepare-windows-build-cache.mjs','check-windows-gui-binaries.mjs','check-desktop-packaging.mjs'])assert.ok(installer.includes(marker),`offline installer is missing ${marker}`);

const peSelfTest=spawnSync(process.execPath,[path.join(root,'scripts','check-windows-gui-binaries.mjs'),'--self-test'],{cwd:root,stdio:'inherit',shell:false});
if(peSelfTest.error)throw peSelfTest.error;
assert.equal(peSelfTest.status,0,'Windows GUI PE parser self-test failed');

const selfTest=spawnSync(process.execPath,[path.join(root,'scripts','prepare-windows-build-cache.mjs'),'--self-test'],{cwd:root,stdio:'inherit',shell:false});
if(selfTest.error)throw selfTest.error;
assert.equal(selfTest.status,0,'Windows build cache self-test failed');
for(const [script,args,label] of [
  ['check-desktop-packaging.mjs',[],'desktop packaging source contract'],
  ['check-desktop-packaging.mjs',['--self-test'],'desktop packaging parser'],
  ['check-desktop-startup-smoke.mjs',['--self-test'],'desktop startup smoke marker'],
]){
  const result=spawnSync(process.execPath,[path.join(root,'scripts',script),...args],{cwd:root,stdio:'inherit',shell:false});
  if(result.error)throw result.error;
  assert.equal(result.status,0,`${label} self-test failed`);
}
console.log(`Windows native audit OK: ${rustFiles.length} Rust files, ${syncSites} durable flush sites, explicit GUI/daemon packaging, startup watchdog, focus ACK and physical smoke gates verified`);

#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import {createHash} from 'node:crypto';
import {spawn} from 'node:child_process';

const root=path.resolve(import.meta.dirname,'..');
const cacheRoot=path.join(root,'.klipper-build-cache');
const targetRoot=path.join(cacheRoot,'target');
// SQLite and NSIS use legacy Windows path limits. Keep temporary paths short
// and separate each checkout without inheriting its full directory depth.
const tempRoot=process.platform==='win32'
  ?path.join(os.tmpdir(),'kf-build',createHash('sha256').update(root).digest('hex').slice(0,16))
  :path.join(cacheRoot,'temp');
const logRoot=path.join(cacheRoot,'logs');
const logPath=path.join(logRoot,'BUILD-AND-INSTALL.log');
const failurePath=path.join(logRoot,'BUILD-FAILURE.txt');
const installerRoot=path.join(root,'INSTALLER');
const rustVendor=path.join(root,'rv');
const rustArchive=path.join(root,'offline-tools','rust','rust-vendor-v1144.tar.gz');
const nsisArchive=path.join(root,'offline-tools','nsis','nsis-3.11.zip');
const nsisPlugin=path.join(root,'offline-tools','nsis','nsis_tauri_utils-0.5.3.dll');
const nsisTools=path.join(targetRoot,'.tauri','NSIS');
const tauriCli=path.join(root,'offline-tools','tauri-cli','node_modules','@tauri-apps','cli','tauri.js');
const offlineConfig=path.join(root,'src-tauri','tauri.offline.conf.json');
const manifestVerifier=path.join(root,'scripts','verify-release-manifest.ps1');
const releaseManifest=path.join(root,'MANIFEST-SHA256.txt');
const offlineManifest=path.join(root,'OFFLINE-PAYLOAD-SHA256.txt');
const cargoManifest=path.join(root,'src-tauri','Cargo.toml');
const buildIdFile=path.join(root,'RELEASE-BUILD-ID.txt');

const stages=[
  'required tools','package integrity','frontend payload','build cache fingerprint',
  'offline payload extraction','Cargo metadata',
  'Rust tests','Clippy','daemon sidecar','Windows IPC probe','NSIS build',
  'desktop binary checks','installer collection',
];

if(process.argv.includes('--self-test')){
  if(stages.length!==13||new Set(stages).size!==stages.length)throw new Error('clean installer stage inventory is invalid');
  for(const required of [rustArchive,nsisArchive,nsisPlugin,tauriCli,offlineConfig,manifestVerifier,releaseManifest,offlineManifest,cargoManifest,buildIdFile]){
    if(!fs.existsSync(required))throw new Error(`missing packaged input: ${path.relative(root,required)}`);
  }
  console.log(`R9.9 direct NSIS installer self-test OK: ${stages.length} linear stages, one entry point and one full log`);
  process.exit(0);
}

fs.mkdirSync(logRoot,{recursive:true});
const log=fs.createWriteStream(logPath,{flags:'w'});
let currentStage='initialization';

const write=(stream,text)=>{
  stream.write(text);
  log.write(text);
};
const out=text=>write(process.stdout,String(text));
const err=text=>write(process.stderr,String(text));
const line=text=>out(`${text}\n`);

class StageFailure extends Error{
  constructor(stage,command,exitCode){
    super(`${stage} failed with exit code ${exitCode}`);
    this.stage=stage;
    this.command=command;
    this.exitCode=exitCode;
  }
}

const cleanDisplay=(command,args)=>[command,...args].map(value=>String(value).includes(' ')?`"${value}"`:value).join(' ');
const run=(stage,command,args=[],options={})=>new Promise((resolve,reject)=>{
  currentStage=stage;
  const display=cleanDisplay(command,args);
  line(`\n[${stage}]`);
  line(`> ${display}`);
  const child=spawn(command,args,{
    cwd:options.cwd??root,
    env:options.env??buildEnv,
    shell:false,
    windowsHide:false,
    stdio:['inherit','pipe','pipe'],
  });
  child.stdout.on('data',chunk=>write(process.stdout,chunk));
  child.stderr.on('data',chunk=>write(process.stderr,chunk));
  child.once('error',error=>reject(new StageFailure(stage,`${display}: ${error.message}`,1)));
  child.once('close',(code,signal)=>{
    if(code===0)return resolve();
    reject(new StageFailure(stage,signal?`${display} (signal ${signal})`:display,Number.isInteger(code)?code:1));
  });
});

const runNode=(stage,relative,args=[])=>run(stage,process.execPath,[path.join(root,relative),...args]);

const ensureInsideRoot=candidate=>{
  const resolved=path.resolve(candidate);
  const prefix=`${root}${path.sep}`.toLowerCase();
  if(!resolved.toLowerCase().startsWith(prefix))throw new Error(`refusing path outside project: ${resolved}`);
  return resolved;
};
const removeOwned=candidate=>{
  const resolved=ensureInsideRoot(candidate);
  fs.rmSync(resolved,{recursive:true,force:true,maxRetries:5,retryDelay:100});
};
const requireFile=file=>{
  if(!fs.existsSync(file)||!fs.statSync(file).isFile())throw new StageFailure(currentStage,`missing ${path.relative(root,file)}`,1);
};
const findFiles=(directory,predicate)=>{
  if(!fs.existsSync(directory))return [];
  const found=[];
  for(const entry of fs.readdirSync(directory,{withFileTypes:true})){
    const absolute=path.join(directory,entry.name);
    if(entry.isDirectory())found.push(...findFiles(absolute,predicate));
    else if(entry.isFile()&&predicate(absolute))found.push(absolute);
  }
  return found;
};

const buildEnv={
  ...process.env,
  CARGO_HOME:path.join(cacheRoot,'cargo'),
  CARGO_TARGET_DIR:targetRoot,
  TEMP:tempRoot,
  TMP:tempRoot,
  CARGO_NET_OFFLINE:'true',
  CARGO_INCREMENTAL:'0',
  CARGO_PROFILE_RELEASE_DEBUG:'0',
  CARGO_PROFILE_RELEASE_INCREMENTAL:'false',
};
// Windows PowerShell 5.1 must build its own module path when launched by pwsh.
for(const name of Object.keys(buildEnv))if(name.toLowerCase()==='psmodulepath')delete buildEnv[name];

const verifyManifest=(kind,file)=>run(`${kind} manifest`, 'powershell.exe',[
  '-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass',
  '-File',manifestVerifier,'-ManifestPath',file,'-RootPath',root,'-Kind',kind,
]);

const closeLog=()=>new Promise(resolve=>log.end(resolve));

try{
  line('============================================================');
  line('  Klipper Farm v1.14.5 - R117 Startup and Hello');
  line('============================================================');
  line(`Project: ${root}`);
  line(`Full log: ${logPath}`);
  const buildId=fs.readFileSync(buildIdFile,'utf8').trim();
  if(!/^[A-Z0-9][A-Z0-9._-]{7,95}$/.test(buildId))throw new StageFailure('package integrity','RELEASE-BUILD-ID.txt is missing or malformed',1);
  line(`Release build ID: ${buildId}`);

  if(process.platform!=='win32'||process.arch!=='x64')throw new StageFailure('required tools',`requires win32-x64, found ${process.platform}-${process.arch}`,1);
  const [nodeMajor,nodeMinor]=process.versions.node.split('.').map(Number);
  if(nodeMajor<20||(nodeMajor===20&&nodeMinor<11))throw new StageFailure('required tools',`Node ${process.versions.node}; required 20.11+`,1);

  fs.mkdirSync(cacheRoot,{recursive:true});
  fs.mkdirSync(buildEnv.CARGO_HOME,{recursive:true});
  fs.mkdirSync(targetRoot,{recursive:true});
  fs.mkdirSync(tempRoot,{recursive:true});
  removeOwned(installerRoot);

  await run('required tools',process.execPath,['--version']);
  await run('required tools','cargo',['--version']);
  await run('required tools','rustc',['--version']);
  await run('required tools','cargo',['clippy','--version']);
  await run('required tools','tar',['--version']);
  await run('required tools','powershell.exe',['-NoLogo','-NoProfile','-NonInteractive','-Command','$PSVersionTable.PSVersion.ToString()']);

  const disk=fs.statfsSync(root);
  const freeBytes=Number(disk.bavail)*Number(disk.bsize);
  line(`Free space: ${Math.floor(freeBytes/1024/1024/1024)} GB`);
  if(freeBytes<12*1024**3)throw new StageFailure('required tools','at least 12 GB free space is required',2);

  currentStage='package integrity';
  for(const file of [rustArchive,nsisArchive,nsisPlugin,tauriCli,offlineConfig,manifestVerifier,releaseManifest,offlineManifest,cargoManifest,buildIdFile])requireFile(file);
  await verifyManifest('release',releaseManifest);
  await verifyManifest('offline',offlineManifest);
  await runNode('frontend payload','scripts/check-production-bundle.mjs');
  await runNode('build cache fingerprint','scripts/prepare-windows-build-cache.mjs');

  currentStage='offline payload extraction';
  const vendorMarker=path.join(rustVendor,'.kf-v1144-complete');
  if(!fs.existsSync(vendorMarker)){
    removeOwned(rustVendor);
    await run('offline payload extraction','tar',['-xzf',rustArchive,'-C',root]);
    requireFile(path.join(rustVendor,'serde-1.0.229','Cargo.toml'));
    fs.writeFileSync(vendorMarker,'verified\n');
  }
  const nsisExecutable=path.join(nsisTools,'makensis.exe');
  const nsisPluginTarget=path.join(nsisTools,'Plugins','x86-unicode','additional','nsis_tauri_utils.dll');
  if(!fs.existsSync(nsisExecutable)||!fs.existsSync(nsisPluginTarget)){
    removeOwned(nsisTools);
    removeOwned(path.join(targetRoot,'.tauri','nsis-3.11'));
    fs.mkdirSync(path.join(targetRoot,'.tauri'),{recursive:true});
    await run('offline payload extraction','powershell.exe',['-NoLogo','-NoProfile','-NonInteractive','-Command',
      '$ErrorActionPreference="Stop"; Expand-Archive -LiteralPath $env:KF_NSIS_ARCHIVE -DestinationPath (Join-Path $env:CARGO_TARGET_DIR ".tauri") -Force'],{
      env:{...buildEnv,KF_NSIS_ARCHIVE:nsisArchive},
    });
    fs.renameSync(path.join(targetRoot,'.tauri','nsis-3.11'),nsisTools);
    fs.mkdirSync(path.dirname(nsisPluginTarget),{recursive:true});
    fs.copyFileSync(nsisPlugin,nsisPluginTarget);
  }
  requireFile(nsisExecutable);
  requireFile(nsisPluginTarget);

  await run('Cargo metadata','cargo',['metadata','--offline','--locked','--manifest-path',cargoManifest,'--format-version','1','--no-deps']);
  await run('update cache cleanup','powershell.exe',['-NoLogo','-NoProfile','-NonInteractive','-File',path.join(root,'scripts','check-update-cache.ps1')]);
  await runNode('update gate','scripts/check-update-gate.mjs');
  await runNode('HTTP keep-alive regression','scripts/check-http-keepalive.mjs');
  await runNode('native upload regression','scripts/check-native-upload-runtime.mjs');
  await runNode('native REST RPC regression','scripts/check-native-rest-rpc-runtime.mjs');
  await runNode('Rust tests','scripts/run-rust-tests.mjs');
  await run('Clippy','cargo',['clippy','--offline','--locked','--workspace','--all-targets','--features','fault-injection','--manifest-path',cargoManifest]);

  await runNode('daemon sidecar','scripts/prepare-sidecar.mjs');
  await run('Windows IPC probe','cargo',['build','--offline','--locked','--release','--manifest-path',cargoManifest,'--bin','klipper-farm-ipc-probe']);

  await run('NSIS build',process.execPath,[tauriCli,'build','--bundles','nsis','--config',offlineConfig,'--ci']);
  const desktopExe=path.join(targetRoot,'release','klipper-farm-client.exe');
  const daemonExe=path.join(targetRoot,'release','klipper-farmd.exe');
  const probeExe=path.join(targetRoot,'release','klipper-farm-ipc-probe.exe');
  for(const file of [desktopExe,daemonExe,probeExe])requireFile(file);
  await runNode('desktop binary checks','scripts/check-windows-gui-binaries.mjs',[desktopExe,daemonExe]);
  await runNode('desktop binary checks','scripts/check-desktop-packaging.mjs',['--generated-root',path.join(targetRoot,'release','nsis')]);

  currentStage='installer collection';
  fs.mkdirSync(installerRoot,{recursive:true});
  const installers=findFiles(path.join(targetRoot,'release','bundle','nsis'),file=>file.toLowerCase().endsWith('.exe')).sort();
  if(!installers.length)throw new StageFailure(currentStage,'NSIS setup.exe was not found',1);
  for(const source of installers)fs.copyFileSync(source,path.join(installerRoot,path.basename(source)));
  const installer=path.join(installerRoot,path.basename(installers.at(-1)));

  line('\n============================================================');
  line('  BUILD SUCCESSFUL');
  line('============================================================');
  line(`Installer: ${installer}`);
  line(`Full log: ${logPath}`);
  await closeLog();
  if(!process.argv.includes('--build-only'))spawn(installer,[],{detached:true,stdio:'ignore',cwd:installerRoot}).unref();
  process.exitCode=0;
}catch(error){
  const failure=error instanceof StageFailure
    ? error
    : new StageFailure(currentStage,error instanceof Error?error.stack??error.message:String(error),1);
  const summary=[
    'BUILD AND INSTALL FAILED',
    `Stage: ${failure.stage}`,
    `Exit code: ${failure.exitCode}`,
    `Command/detail: ${failure.command}`,
    `Full log: ${logPath}`,
    '',
  ].join('\r\n');
  err(`\n============================================================\n  BUILD AND INSTALL FAILED\n============================================================\n`);
  err(`Stage: ${failure.stage}\nExit code: ${failure.exitCode}\nCommand/detail: ${failure.command}\n`);
  err(`Full log: ${logPath}\n`);
  fs.writeFileSync(failurePath,summary);
  await closeLog();
  process.exitCode=failure.exitCode||1;
}

const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),ts=require(path.join(root,'node_modules/typescript'));
