#!/usr/bin/env node
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

const root=path.resolve(import.meta.dirname,'..');
const baseline=process.env.KF_R117_BASELINE;
assert.ok(baseline,'KF_R117_BASELINE must point to the verified published R116 source snapshot');
const read=(base,relative)=>fs.readFileSync(path.join(base,relative),'utf8');
const srcBase=path.join(baseline,'src');
const nativeBase=fs.existsSync(path.join(baseline,'native'))?path.join(baseline,'native'):path.join(baseline,'src-tauri');
const files=directory=>fs.readdirSync(directory,{withFileTypes:true}).flatMap(entry=>{
 const absolute=path.join(directory,entry.name);
 assert.ok(!entry.isSymbolicLink(),'Unexpected symlink in checked source: '+absolute);
 return entry.isDirectory()?files(absolute):[absolute];
});
const allowedSource=new Set(['components/LoginPanel.tsx','components/ControlPanel.tsx','components/JobPartPreview.tsx','lib/moonraker.ts','lib/afterPanelPaint.ts']);
const allowedNative=new Set(['src/lib.rs','src/transactional_core/instance_lease.rs']);
let exactFiles=0;
for(const [folder,base,allowed] of [['src',srcBase,allowedSource],['src-tauri',nativeBase,allowedNative]]){
 const currentRoot=path.join(root,folder);
 const packaged=relative=>folder!=='src-tauri'||!['target/','binaries/'].some(prefix=>relative.startsWith(prefix));
 const oldPaths=new Set(files(base).map(file=>path.relative(base,file).replaceAll('\\','/')).filter(packaged));
 const currentPaths=new Set(files(currentRoot).map(file=>path.relative(currentRoot,file).replaceAll('\\','/')).filter(packaged));
 for(const relative of new Set([...oldPaths,...currentPaths])){
  if(allowed.has(relative))continue;
  assert.ok(oldPaths.has(relative)&&currentPaths.has(relative),'Protected source inventory changed: '+folder+'/'+relative);
  assert.ok(fs.readFileSync(path.join(base,relative)).equals(fs.readFileSync(path.join(currentRoot,relative))),'Protected file changed: '+folder+'/'+relative);
  exactFiles++;
 }
}

// Native IPC, authentication, printing, file transfer and light implementations
// precede run(); the command registry and the remainder of run_desktop follow
// invoke_handler. Only desktop ownership and startup setup may change between.
const startupBoundary='#[cfg_attr(mobile, tauri::mobile_entry_point)]';
const handlerBoundary='        .invoke_handler(tauri::generate_handler![';
const stripStartup=value=>{
 const begin=value.indexOf(startupBoundary),end=value.indexOf(handlerBoundary,begin);
 assert.ok(begin>=0&&end>begin,'Native startup boundaries missing');
 return value.slice(0,begin)+'/* R117 desktop ownership/startup */\n'+value.slice(end);
};
assert.ok(stripStartup(read(root,'src-tauri/src/lib.rs'))===stripStartup(read(nativeBase,'src/lib.rs')),'Native command implementations or registry changed outside desktop startup');

// Strip only the explicitly read-only methods used by the detail preview.
// Everything left, including every light, print and upload method, must match.
const readMethods=new Set(['objectList','macros','webcams','history','metadata','thumbnails','loadThumbnailDataUrl','thumbnailDataUrl']);
const stripReadMethods=original=>{
 const value=original.replace('type ThumbnailReadOptions={allowEmbeddedGcode?:boolean;signal?:AbortSignal};\n','');
 const method=/^  (?:private |public |protected )?(?:async )?([A-Za-z_$][\w$]*)\(/gm;
 const matches=[...value.matchAll(method)];
 const ranges=matches.flatMap((match,index)=>readMethods.has(match[1])?[[match.index,matches[index+1]?.index??value.length,match[1]]]:[]);
 assert.equal(ranges.length,readMethods.size,'Read-only method inventory changed');
 let result='',offset=0;
 for(const [begin,end,name] of ranges){result+=value.slice(offset,begin)+`  /* R117 read-only ${name} */\n`;offset=end;}
 return result+value.slice(offset);
};
assert.ok(stripReadMethods(read(root,'src/lib/moonraker.ts'))===stripReadMethods(read(srcBase,'lib/moonraker.ts')),'Printer commands or client transport changed outside allowed read-only methods');

// The PIN dial is shared by the unchanged PIN/password authentication path.
const pinDial=value=>value.slice(value.indexOf('const PIN_LENGTH='),value.indexOf('export function LoginPanel('));
assert.ok(pinDial(read(root,'src/components/LoginPanel.tsx'))===pinDial(read(srcBase,'components/LoginPanel.tsx')),'PIN entry component changed outside Windows Hello presentation');

const between=(value,start,end)=>{
 const begin=value.indexOf(start),finish=value.indexOf(end,begin);
 assert.ok(begin>=0&&finish>begin,'ControlPanel protection boundary missing: '+start);
 return value.slice(begin,finish);
};
const oldPanel=read(srcBase,'components/ControlPanel.tsx'),panel=read(root,'src/components/ControlPanel.tsx');
for(const [start,end] of [['  const run=','  const progress='],['  const setPrinterLight=','  const connecting=']]){
 assert.ok(between(panel,start,end)===between(oldPanel,start,end),'ControlPanel mutation helper changed: '+start);
}
const mutationLines=value=>value.split('\n').filter(line=>/\bclient!?\.(?:pause|resume|cancel|emergencyStop|restart|firmwareRestart|start|gcode|setNozzle|setBed|setFan|setSpeed|home|jog|extrude|runMacro|serviceCommand|light|deleteFile|enqueue|queueStart|queuePause|queueRemove|setActiveSpool|upload|cancelUpload)\(/.test(line)).join('\n');
assert.ok(mutationLines(panel)===mutationLines(oldPanel),'ControlPanel mutation callbacks changed outside read-only preview work');

console.log(`R117 scope passed: ${exactFiles} exact protected files; native auth/commands/registry and printer transport/print/light/upload methods match published R116 byte for byte.`);

