[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)][string]$DesktopExe,
    [Parameter(Mandatory = $true)][string]$OutputDirectory
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if (-not $IsWindows) { throw 'The real desktop instance proof must run on Windows.' }
$desktopPath = (Resolve-Path -LiteralPath $DesktopExe).Path
if ([IO.Path]::GetFileName($desktopPath) -ine 'klipper-farm-client.exe') {
    throw 'The proof must launch the installed klipper-farm-client.exe.'
}
[IO.Directory]::CreateDirectory($OutputDirectory) | Out-Null
$proofRoot = (Resolve-Path -LiteralPath $OutputDirectory).Path
Add-Type @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class KFInstanceR117 {
    public delegate bool EnumProc(IntPtr window, IntPtr parameter);
    [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc callback, IntPtr parameter);
    [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr window);
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr window, out uint pid);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetWindowText(IntPtr window, StringBuilder text, int count);
    [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
    public static string[] VisibleTitles(int pid) {
        var titles = new List<string>();
        EnumWindows((window, parameter) => {
            uint owner; GetWindowThreadProcessId(window, out owner);
            if (owner == (uint)pid && IsWindowVisible(window)) {
                var title = new StringBuilder(1024); GetWindowText(window, title, title.Capacity);
                if (title.Length > 0) titles.Add(title.ToString());
            }
            return true;
        }, IntPtr.Zero);
        return titles.ToArray();
    }
    public static int ForegroundPid() {
        uint pid; GetWindowThreadProcessId(GetForegroundWindow(), out pid); return (int)pid;
    }
}
'@

function Start-ProofDesktop([string]$CaseRoot) {
    $start = [Diagnostics.ProcessStartInfo]::new($desktopPath)
    $start.UseShellExecute = $false
    $start.WorkingDirectory = [IO.Path]::GetDirectoryName($desktopPath)
    foreach ($entry in @{APPDATA = 'Roaming'; LOCALAPPDATA = 'Local'; TEMP = 'Temp'; TMP = 'Temp'}.GetEnumerator()) {
        $value = Join-Path $CaseRoot $entry.Value
        [IO.Directory]::CreateDirectory($value) | Out-Null
        $start.Environment[$entry.Key] = $value
    }
    return [Diagnostics.Process]::Start($start)
}

function Read-StartupLog([string]$CaseRoot) {
    $logPath = Join-Path $CaseRoot 'Roaming/app.klipper.farm/logs/desktop-startup.log'
    if (Test-Path -LiteralPath $logPath) { return [IO.File]::ReadAllText($logPath) }
    return ''
}

function Stop-OwnedDesktop([Diagnostics.Process]$Process) {
    if ($null -eq $Process -or $Process.HasExited) { return }
    $Process.Refresh()
    [void]$Process.CloseMainWindow()
    if (-not $Process.WaitForExit(10000)) {
        # Failure cleanup is restricted to the exact process this proof started.
        # Never kill a process by product name or touch an existing user session.
        $Process.Kill()
        [void]$Process.WaitForExit(5000)
        throw "Owned desktop PID $($Process.Id) did not close gracefully."
    }
}

$results = [Collections.Generic.List[object]]::new()
foreach ($case in @(
    @{Name = 'immediate'; DelayMs = 0; WaitForReady = $false},
    @{Name = 'startup-100ms'; DelayMs = 100; WaitForReady = $false},
    @{Name = 'already-ready'; DelayMs = 0; WaitForReady = $true}
)) {
    $caseRoot = Join-Path $proofRoot $case.Name
    if (Test-Path -LiteralPath $caseRoot) { throw "Proof destination already exists: $caseRoot" }
    [IO.Directory]::CreateDirectory($caseRoot) | Out-Null
    $processes = [Collections.Generic.List[Diagnostics.Process]]::new()
    $timer = [Diagnostics.Stopwatch]::StartNew()
    try {
        $first = Start-ProofDesktop $caseRoot
        $processes.Add($first)
        if ($case.WaitForReady) {
            $readyDeadline = [DateTime]::UtcNow.AddSeconds(40)
            while ((Read-StartupLog $caseRoot) -notmatch "pid=$($first.Id) code=DESKTOP_WINDOW_READY ") {
                if ($first.HasExited) { throw 'The first desktop exited before the WebView was ready.' }
                if ([DateTime]::UtcNow -gt $readyDeadline) { throw 'The first WebView did not become ready.' }
                Start-Sleep -Milliseconds 100
            }
        }
        if ($case.DelayMs -gt 0) { Start-Sleep -Milliseconds $case.DelayMs }
        $focusTimer = [Diagnostics.Stopwatch]::StartNew()
        $second = Start-ProofDesktop $caseRoot
        $processes.Add($second)
        $focusDeadline = [DateTime]::UtcNow.AddSeconds(40)
        $owner = $null
        $secondary = $null
        while ([DateTime]::UtcNow -lt $focusDeadline) {
            $alive = @($processes | Where-Object { -not $_.HasExited })
            $exited = @($processes | Where-Object { $_.HasExited })
            if ($alive.Count -eq 0) { throw 'Both desktop launches exited; no instance owns the window.' }
            $log = Read-StartupLog $caseRoot
            if ($log -match 'code=(DESKTOP_INSTANCE_LEASE_FAILED|FOCUS_LISTENER_START_FAILED|DESKTOP_WINDOW_READY_TIMEOUT|TAURI_DESKTOP_RUN_FAILED) ') {
                throw 'A desktop startup failure was recorded; see the case startup log.'
            }
            if ($alive.Count -eq 1 -and $exited.Count -eq 1) {
                $candidate = $alive[0]
                $other = $exited[0]
                if ($other.ExitCode -ne 0) { throw "Secondary launch exited with code $($other.ExitCode)." }
                $ready = $log -match "pid=$($candidate.Id) code=DESKTOP_WINDOW_READY "
                $focused = $log -match "pid=$($other.Id) code=SECONDARY_INSTANCE_FOCUS_REQUESTED "
                if ($ready -and $focused) { $owner = $candidate; $secondary = $other; break }
            }
            Start-Sleep -Milliseconds 100
        }
        if ($null -eq $owner) { throw 'The two launches did not settle to one focused owner within 40 seconds.' }
        if ($case.WaitForReady -and $focusTimer.ElapsedMilliseconds -gt 5000) {
            throw 'Focusing an already-ready desktop took more than 5 seconds.'
        }
        $titles = @([KFInstanceR117]::VisibleTitles($owner.Id))
        $mainWindows = @($titles | Where-Object { $_ -eq 'Klipper Farm' })
        if ($mainWindows.Count -ne 1) { throw "Expected one visible main window; found $($mainWindows.Count)." }
        if (@($titles | Where-Object { $_ -match 'ошибка запуска' }).Count -ne 0) { throw 'A fatal startup modal is visible.' }
        if ([KFInstanceR117]::ForegroundPid() -ne $owner.Id) { throw 'The acknowledged existing main window was not foregrounded.' }
        $results.Add([ordered]@{
            case = $case.Name
            ownerPid = $owner.Id
            secondaryPid = $secondary.Id
            secondaryExitCode = $secondary.ExitCode
            mainWindowCount = $mainWindows.Count
            foregroundConfirmed = $true
            focusAcknowledged = $true
            webViewReady = $true
            elapsedMs = $timer.ElapsedMilliseconds
            secondaryFocusMs = $focusTimer.ElapsedMilliseconds
        })
        Stop-OwnedDesktop $owner
        if ($owner.ExitCode -ne 0) { throw "The owner closed with code $($owner.ExitCode)." }
        Write-Host "Desktop instance race OK: $($case.Name), one visible main window, authenticated focus ACK, clean exit."
    }
    finally {
        foreach ($process in $processes) {
            if (-not $process.HasExited) {
                try { Stop-OwnedDesktop $process } catch { Write-Warning $_ }
            }
            $process.Dispose()
        }
        [IO.File]::WriteAllText((Join-Path $caseRoot 'startup-proof.log'), (Read-StartupLog $caseRoot))
    }
}
$proof = [ordered]@{schemaVersion = 1; executable = $desktopPath; cases = $results.ToArray()}
[IO.File]::WriteAllText((Join-Path $proofRoot 'startup-instance-r117.json'), ($proof | ConvertTo-Json -Depth 6))
Write-Host 'R117 installed desktop startup proof passed: 3 real double-launch cases.'

