const PIN_LENGTH=6;
function PinDial({value,onChange,disabled=false}:{value:string;onChange:(value:string)=>void;disabled?:boolean}){
 const add=(digit:string)=>{if(!disabled&&value.length<PIN_LENGTH)onChange(`${value}${digit}`)};
 return <div className="phonePin" role="group" aria-label="Цифровая клавиатура PIN-кода" tabIndex={0} onKeyDown={event=>{if(disabled)return;if(/^\d$/.test(event.key)){event.preventDefault();add(event.key)}else if(event.key==='Backspace'){event.preventDefault();onChange(value.slice(0,-1))}else if(event.key==='Delete'){event.preventDefault();onChange('')}}}>
  <output className="phonePinDisplay" aria-label={`Введено цифр: ${value.length} из ${PIN_LENGTH}`}>{Array.from({length:PIN_LENGTH},(_,index)=><i key={index} className={index<value.length?'filled':''}/>)}</output>
  <div className="phonePinKeys">{['1','2','3','4','5','6','7','8','9'].map(digit=><button key={digit} type="button" disabled={disabled} onClick={()=>add(digit)}>{digit}</button>)}<button type="button" className="pinUtility" disabled={disabled||!value} onClick={()=>onChange('')} aria-label="Очистить PIN">C</button><button type="button" disabled={disabled} onClick={()=>add('0')}>0</button><button type="button" className="pinUtility" disabled={disabled||!value} onClick={()=>onChange(value.slice(0,-1))} aria-label="Удалить последнюю цифру">⌫</button></div>
 </div>
}

export function LoginPanel({needsSetup,onAuthenticated}:{needsSetup:boolean;onAuthenticated:(session:AuthSession)=>void}){
 const [userId,setUserId]=useState(preferredLoginUser),[password,setPassword]=useState(''),[confirmPassword,setConfirmPassword]=useState('');
 const [mode,setMode]=useState<LoginMethod>(()=>needsSetup&&preferredLoginMethod()==='hello'?'password':preferredLoginMethod());
 const [pin,setPin]=useState(''),[pinConfirm,setPinConfirm]=useState(''),[changeUser,setChangeUser]=useState(false);
 const [busy,setBusy]=useState(false),[error,setError]=useState(''),[hello,setHello]=useState<{userId:string;status:HelloStatus}>(),[checkingHello,setCheckingHello]=useState(false);
 const busyRef=useRef(false),mounted=useRef(true),autoHelloAttempted=useRef(new Set<string>());
 const account=userId.trim().toLowerCase();
 useEffect(()=>{mounted.current=true;return()=>{mounted.current=false}},[]);
 useEffect(()=>{
  if(needsSetup||mode!=='hello'){setHello(undefined);setCheckingHello(false);return}
  let cancelled=false;setHello(undefined);setCheckingHello(true);setError('');
  if(!account){setCheckingHello(false);return}
  helloStatus(account).then(status=>{if(!cancelled)setHello({userId:account,status})}).catch(e=>{if(!cancelled)setError(String(e))}).finally(()=>{if(!cancelled)setCheckingHello(false)});
  return()=>{cancelled=true}
 },[mode,account,needsSetup]);
 const helloReady=!checkingHello&&hello?.userId===account&&hello.status.available&&hello.status.enrolled;
 const canSubmit=needsSetup?(mode==='pin'?pin.length===6&&pinConfirm.length===6:!!password&&!!confirmPassword):!!account&&(mode==='password'?!!password:mode==='hello'?!!helloReady&&!changeUser:pin.length===6);
 const authenticate=useCallback(async()=>{
  if(busyRef.current||!canSubmit)return;setError('');
  if(needsSetup&&mode==='password'&&password!==confirmPassword)return setError('Пароли не совпадают.');
  if(needsSetup&&mode==='pin'&&(pin.length!==PIN_LENGTH||pin!==pinConfirm))return setError('Введите одинаковый PIN из 6 цифр.');
  // A synchronous guard also covers a click arriving before React renders busy.
  busyRef.current=true;setBusy(true);
  if(mode==='hello')autoHelloAttempted.current.add(account);
  try{const session=needsSetup?await bootstrapAuth(mode==='password'?password:'',mode==='pin'?pin:undefined):mode==='pin'?await loginWithPin(account,pin):mode==='hello'?await loginWithHello(account):await login(account,password);if(mounted.current){saveLoginMethod(mode);onAuthenticated(session)}}
  catch(value){if(mounted.current){setError(String(value instanceof Error?value.message:value));if(mode==='pin')setPin('')}}
  finally{busyRef.current=false;if(mounted.current)setBusy(false)}
 },[canSubmit,needsSetup,mode,password,confirmPassword,pin,pinConfirm,account,onAuthenticated]);
 useEffect(()=>{
  if(needsSetup||mode!=='hello'||changeUser||!helloReady||autoHelloAttempted.current.has(account))return;
  let cancelled=false,frame=0;
  const ready=()=>!cancelled&&!busyRef.current&&!autoHelloAttempted.current.has(account)&&document.readyState!=='loading'&&document.visibilityState==='visible'&&document.hasFocus();
  const attempt=()=>{if(!ready()||frame)return;frame=window.requestAnimationFrame(()=>{frame=0;if(ready())void authenticate()})};
  // Wait for a painted, foreground window so the OS verification has a ready owner.
  window.addEventListener('focus',attempt);document.addEventListener('visibilitychange',attempt);document.addEventListener('DOMContentLoaded',attempt);attempt();
  return()=>{cancelled=true;if(frame)window.cancelAnimationFrame(frame);window.removeEventListener('focus',attempt);document.removeEventListener('visibilitychange',attempt);document.removeEventListener('DOMContentLoaded',attempt)}
 },[needsSetup,mode,changeUser,helloReady,account,authenticate]);
 useEffect(()=>{if(needsSetup||mode!=='pin'||pin.length!==PIN_LENGTH||busy||!account)return;const timer=window.setTimeout(()=>void authenticate(),100);return()=>window.clearTimeout(timer)},[pin,mode,needsSetup,account,busy,authenticate]);
 const selectMode=(next:LoginMethod)=>{if(busyRef.current)return;setMode(next);setPassword('');setConfirmPassword('');setPin('');setPinConfirm('');setError('');setChangeUser(false);saveLoginMethod(next)};
 const submit=(event:FormEvent)=>{event.preventDefault();if(canSubmit)void authenticate()};
 return <main className="authScreen"><section className="authCard authSingleMethod">
  <div className="authBrand"><img src={appIcon} alt=""/><div><span>KLIPPER FARM</span><b>УПРАВЛЕНИЕ ФЕРМОЙ</b></div></div>
  <div className="authIcon">{mode==='hello'?<Fingerprint/>:mode==='pin'?<LockKeyhole/>:<KeyRound/>}</div>
  <h1>{needsSetup?'Настройте вход':'Вход в Klipper Farm'}</h1><p>{needsSetup?'Выберите удобный способ доступа к программе.':mode==='hello'?'Подтвердите вход в системном окне Windows.':mode==='pin'?'Введите ваш шестизначный PIN-код.':'Введите логин и пароль.'}</p>
  <form onSubmit={submit}>
   <label className="authMethodChoice"><span>Способ входа</span><select aria-label="Способ входа" value={mode} disabled={busy} onChange={e=>selectMode(e.target.value as LoginMethod)}><option value="password">Логин и пароль</option><option value="pin">PIN-код</option>{!needsSetup&&<option value="hello">Отпечаток · Windows Hello</option>}</select></label>
   {!needsSetup&&(mode==='password'||changeUser)?<><label><span>Логин</span><input autoFocus autoComplete="username" disabled={busy} value={userId} onChange={e=>{setUserId(e.target.value.toLowerCase());setPin('');setError('')}} maxLength={64}/></label>{changeUser&&mode!=='password'&&<button type="button" disabled={busy||!account} onClick={()=>setChangeUser(false)}>Продолжить</button>}</>:!needsSetup&&<div className="authAccount"><span>Пользователь: <b>{userId}</b></span><button type="button" disabled={busy} onClick={()=>setChangeUser(true)}>Сменить</button></div>}
   {mode==='password'&&<><label><span>{needsSetup?'Создайте пароль':'Пароль'}</span><input autoFocus={needsSetup} disabled={busy} type="password" autoComplete={needsSetup?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} maxLength={128}/></label>{needsSetup&&<><label><span>Повторите пароль</span><input disabled={busy} type="password" autoComplete="new-password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} maxLength={128}/></label><small>От 12 символов: используйте три типа — регистр, цифры, знаки.</small></>}</>}
   {mode==='pin'&&(needsSetup?<><label><span>PIN — 6 цифр</span><input autoFocus disabled={busy} type="password" inputMode="numeric" autoComplete="new-password" value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,'').slice(0,6))}/></label><label><span>Повторите PIN</span><input disabled={busy} type="password" inputMode="numeric" autoComplete="new-password" value={pinConfirm} onChange={e=>setPinConfirm(e.target.value.replace(/\D/g,'').slice(0,6))}/></label></>:<><PinDial value={pin} onChange={value=>{setPin(value);setError('')}} disabled={busy}/><small className="pinHint">{busy?'Проверяем…':'Вход после шестой цифры'}</small></>)}
   {mode==='hello'&&<div className="authHello"><Fingerprint/><span role="status">{busy?'Приложите палец или подтвердите вход в окне Windows Hello…':checkingHello?'Проверяем Windows Hello…':hello?.userId===account?hello.status.detail:'Не удалось проверить Windows Hello'}</span><small>Отпечаток или другой настроенный способ Windows Hello. Подключается после входа в настройках программы.</small></div>}
   {error&&<div className="authError" role="alert">{error.replace(/^Error:\s*/, '')}</div>}
   {(needsSetup||mode!=='pin')&&<button className="primary" disabled={busy||(mode==='hello'&&checkingHello)||!canSubmit}>{busy?<LoaderCircle className="spin"/>:mode==='hello'?<Fingerprint/>:<ShieldCheck/>}{busy?'Проверяем…':needsSetup?'Сохранить и войти':mode==='hello'?'Войти через Windows Hello':'Войти'}</button>}
  </form><footer>Klipper Farm · 1.14.5</footer>
 </section></main>
}

/** Give a newly opened panel a painted frame before starting optional work. */
export function afterPanelPaint(work:()=>void){
  let disposed=false,timer:number|undefined;
  const frame=window.requestAnimationFrame(()=>{
    timer=window.setTimeout(()=>{if(!disposed)work()},0);
  });
  return()=>{disposed=true;window.cancelAnimationFrame(frame);if(timer!==undefined)window.clearTimeout(timer)};
}

