    #[test]
    fn hello_grant_is_bound_to_account_version_and_current_credentials(){let stamp="a".repeat(64);let mut grant=HelloGrant{version:1,user_id:"admin".into(),credential_stamp:stamp.clone()};assert!(hello_grant_matches(&grant,"admin",&stamp));assert!(!hello_grant_matches(&grant,"operator",&stamp));assert!(!hello_grant_matches(&grant,"admin",&"b".repeat(64)));grant.version=2;assert!(!hello_grant_matches(&grant,"admin",&stamp));grant.version=1;grant.credential_stamp="".into();assert!(!hello_grant_matches(&grant,"admin",&stamp));}
    #[test]
    fn hello_single_flight_releases_after_failure(){let busy=Arc::new(AtomicBool::new(false));assert!(busy.compare_exchange(false,true,Ordering::AcqRel,Ordering::Acquire).is_ok());let guard=HelloBusy(busy.clone());assert!(busy.compare_exchange(false,true,Ordering::AcqRel,Ordering::Acquire).is_err());drop(guard);assert!(!busy.load(Ordering::Acquire));}
}

use std::fs::{self, OpenOptions};
use std::io::{Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{mpsc, Arc};
use std::thread;
use std::time::{Duration, Instant};
use tauri::{AppHandle, Manager};

const LEASE_FILENAME: &str = "klipper-farm-v13.instance.lease";
const LEGACY_FOCUS_MESSAGE: &[u8] = b"KLIPPER_FARM_V13_FOCUS\n";
const FOCUS_PREFIX: &str = "KLIPPER_FARM_V17_FOCUS ";
const FOCUS_ACK: &[u8] = b"KLIPPER_FARM_V20_FOCUSED\n";
const MAX_LEASE_BYTES: u64 = 4 * 1024;
// A second launch can arrive between mutex acquisition, lease publication and
// WebView creation. It waits before constructing its own Tauri window, so the
// primary UI thread remains free to finish startup and accept the focus request.
const FOCUS_READY_TIMEOUT: Duration = Duration::from_secs(30);
const FOCUS_RETRY_INTERVAL: Duration = Duration::from_millis(100);

#[derive(Debug, Clone, PartialEq, Eq)]
struct LeaseRecord {
    pid: Option<u32>,
    port: u16,
    token: Option<String>,
}

pub struct InstanceLease {
    listener: Arc<TcpListener>,
    lease_path: PathBuf,
    token: String,
    stop: Arc<AtomicBool>,
    _platform_guard: platform::Guard,
}

impl InstanceLease {
    pub fn acquire() -> Result<Self, String> {
        let lease_path = std::env::temp_dir().join(LEASE_FILENAME);
        let platform_guard = match platform::acquire()? {
            platform::Acquire::Owned(guard) => guard,
            platform::Acquire::AlreadyRunning => {
                if signal_existing_until_ready(&lease_path, FOCUS_READY_TIMEOUT) {
                    return Err("INSTANCE_ALREADY_RUNNING".into());
                }
                // The first process may have closed during the bounded wait.
                // Never delete its lease or start a second owner while its
                // named mutex is still held.
                match platform::acquire()? {
                    platform::Acquire::Owned(guard) => guard,
                    platform::Acquire::AlreadyRunning => {
                        return Err("INSTANCE_RUNNING_WITHOUT_READY_WINDOW".into());
                    }
                }
            }
        };

        // This recognizes the fixed-port V13–V16 lease too, so an in-place
        // update cannot run beside an older process that is still active.
        if signal_existing_with_retry(&lease_path) {
            return Err("INSTANCE_ALREADY_RUNNING".into());
        }
        if lease_path.exists() {
            fs::remove_file(&lease_path)
                .map_err(|error| format!("Не удалось удалить устаревшую lease: {error}"))?;
        }

        let listener = TcpListener::bind(("127.0.0.1", 0))
            .map_err(|error| format!("Не удалось создать loopback focus transport: {error}"))?;
        listener
            .set_nonblocking(true)
            .map_err(|error| error.to_string())?;
        let port = listener
            .local_addr()
            .map_err(|error| error.to_string())?
            .port();
        let token = hex::encode(crate::random_bytes::<16>()?);
        let mut file = match OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&lease_path)
        {
            Ok(file) => file,
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                thread::sleep(Duration::from_millis(100));
                let _ = signal_existing_with_retry(&lease_path);
                return Err("INSTANCE_ALREADY_RUNNING".into());
            }
            Err(error) => return Err(format!("Не удалось создать lease-файл: {error}")),
        };
        writeln!(
            file,
            "pid={}\nport={port}\ntoken={token}",
            std::process::id()
        )
        .map_err(|error| error.to_string())?;
        file.sync_all().map_err(|error| error.to_string())?;

        Ok(Self {
            listener: Arc::new(listener),
            lease_path,
            token,
            stop: Arc::new(AtomicBool::new(false)),
            _platform_guard: platform_guard,
        })
    }

    pub fn start_focus_listener(
        &self,
        app: AppHandle,
        hello_busy: Arc<AtomicBool>,
    ) -> Result<(), String> {
        let listener = self
            .listener
            .try_clone()
            .map_err(|error| error.to_string())?;
        let expected = focus_message(&self.token);
        let stop = Arc::clone(&self.stop);
        thread::Builder::new()
            .name("klipper-farm-instance-lease".into())
            .spawn(move || {
                while !stop.load(Ordering::Acquire) {
                    match listener.accept() {
                        Ok((mut stream, peer)) => {
                            if !peer.ip().is_loopback() {
                                continue;
                            }
                            let _ = stream.set_read_timeout(Some(Duration::from_millis(500)));
                            let mut message = vec![0_u8; expected.len()];
                            if stream.read_exact(&mut message).is_ok()
                                && message.as_slice() == expected.as_slice()
                            {
                                let focus_app = app.clone();
                                let focus_hello_busy = Arc::clone(&hello_busy);
                                let (focused, result) = mpsc::sync_channel(1);
                                if app
                                    .run_on_main_thread(move || {
                                        let outcome = focus_main_window(&focus_app, &focus_hello_busy);
                                        let _ = focused.send(outcome);
                                    })
                                    .is_ok()
                                    && matches!(
                                        result.recv_timeout(FOCUS_READY_TIMEOUT),
                                        Ok(Ok(()))
                                    )
                                {
                                    let _ = stream.set_write_timeout(Some(Duration::from_millis(500)));
                                    let _ = stream.write_all(FOCUS_ACK);
                                    let _ = stream.flush();
                                }
                            }
                        }
                        Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                            thread::sleep(Duration::from_millis(150));
                        }
                        Err(_) => thread::sleep(Duration::from_millis(250)),
                    }
                }
            })
            .map_err(|error| error.to_string())?;
        Ok(())
    }
}

impl Drop for InstanceLease {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Release);
        if read_lease_record(&self.lease_path)
            .ok()
            .flatten()
            .is_some_and(|record| record.token.as_deref() == Some(self.token.as_str()))
        {
            let _ = fs::remove_file(&self.lease_path);
        }
    }
}

fn focus_main_window(app: &AppHandle, hello_busy: &AtomicBool) -> Result<(), String> {
    let window = app
        .get_webview_window("main")
        .ok_or("MAIN_TAURI_WINDOW_NOT_CREATED")?;
    // The Windows Hello dialog is owned by the main window. Do not steal its
    // focus or dismiss authentication when a shortcut is clicked a second time.
    if !hello_busy.load(Ordering::Acquire) {
        window.unminimize().map_err(|error| error.to_string())?;
        window.show().map_err(|error| error.to_string())?;
        window.set_focus().map_err(|error| error.to_string())?;
    }
    if !window.is_visible().map_err(|error| error.to_string())? {
        return Err("MAIN_TAURI_WINDOW_NOT_VISIBLE".into());
    }
    Ok(())
}

fn signal_existing_instance(path: &Path, deadline: Instant) -> Result<bool, String> {
    let Some(record) = read_lease_record(path)? else {
        return Ok(false);
    };
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        return Ok(false);
    }
    let address = SocketAddr::from(([127, 0, 0, 1], record.port));
    let Ok(mut stream) =
        TcpStream::connect_timeout(&address, remaining.min(Duration::from_millis(500)))
    else {
        return Ok(false);
    };
    if let Some(pid) = record.pid {
        platform::allow_foreground(pid);
    }
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        return Ok(false);
    }
    stream
        .set_write_timeout(Some(remaining.min(Duration::from_millis(500))))
        .map_err(|error| error.to_string())?;
    stream
        .set_read_timeout(Some(remaining))
        .map_err(|error| error.to_string())?;
    let message = record
        .token
        .as_deref()
        .map(focus_message)
        .unwrap_or_else(|| LEGACY_FOCUS_MESSAGE.to_vec());
    stream
        .write_all(&message)
        .map_err(|error| error.to_string())?;
    stream.flush().map_err(|error| error.to_string())?;
    if record.token.is_none() {
        return Ok(true);
    }
    Ok(read_focus_ack(&mut stream, deadline))
}

fn read_focus_ack(stream: &mut TcpStream, deadline: Instant) -> bool {
    let mut acknowledgement = [0_u8; FOCUS_ACK.len()];
    let mut received = 0;
    while received < acknowledgement.len() {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() || stream.set_read_timeout(Some(remaining)).is_err() {
            return false;
        }
        match stream.read(&mut acknowledgement[received..]) {
            Ok(0) | Err(_) => return false,
            Ok(count) => received += count,
        }
    }
    acknowledgement.as_slice() == FOCUS_ACK
}

fn signal_existing_until_ready(path: &Path, timeout: Duration) -> bool {
    signal_existing_with_deadline(path, timeout, platform::owner_present)
}

fn signal_existing_with_retry(path: &Path) -> bool {
    // Compatibility probe for pre-mutex versions. An absent or refused stale
    // lease must not slow down a normal first launch.
    let deadline = Instant::now() + Duration::from_secs(2);
    for attempt in 0..3 {
        if signal_existing_instance(path, deadline).unwrap_or(false) {
            return true;
        }
        if !path.exists() || attempt == 2 || Instant::now() >= deadline {
            return false;
        }
        thread::sleep(FOCUS_RETRY_INTERVAL);
    }
    false
}

fn signal_existing_with_deadline(
    path: &Path,
    timeout: Duration,
    mut owner_present: impl FnMut() -> bool,
) -> bool {
    let deadline = Instant::now() + timeout;
    loop {
        if signal_existing_instance(path, deadline).unwrap_or(false) {
            return true;
        }
        if !owner_present() {
            return false;
        }
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return false;
        }
        thread::sleep(remaining.min(FOCUS_RETRY_INTERVAL));
    }
}

fn focus_message(token: &str) -> Vec<u8> {
    format!("{FOCUS_PREFIX}{token}\n").into_bytes()
}

fn read_lease_record(path: &Path) -> Result<Option<LeaseRecord>, String> {
    let mut file = match fs::File::open(path) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("Не удалось прочитать instance lease: {error}")),
    };
    let mut raw = String::new();
    Read::by_ref(&mut file)
        .take(MAX_LEASE_BYTES)
        .read_to_string(&mut raw)
        .map_err(|error| error.to_string())?;
    parse_lease_record(&raw).map(Some)
}

fn parse_lease_record(raw: &str) -> Result<LeaseRecord, String> {
    let mut pid = None;
    let mut port = None;
    let mut token = None;
    for line in raw.lines().take(8) {
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        match key.trim() {
            "pid" => {
                let parsed = value
                    .trim()
                    .parse::<u32>()
                    .map_err(|_| "Повреждён pid в instance lease")?;
                if parsed == 0 {
                    return Err("Повреждён pid в instance lease".into());
                }
                pid = Some(parsed);
            }
            "port" => {
                let parsed = value
                    .trim()
                    .parse::<u16>()
                    .map_err(|_| "Повреждён port в instance lease")?;
                if parsed == 0 {
                    return Err("Повреждён port в instance lease".into());
                }
                port = Some(parsed);
            }
            "token" => {
                let value = value.trim();
                if value.len() != 32 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
                    return Err("Повреждён token в instance lease".into());
                }
                token = Some(value.to_ascii_lowercase());
            }
            _ => {}
        }
    }
    Ok(LeaseRecord {
        pid,
        port: port.ok_or("Instance lease не содержит port")?,
        token,
    })
}

#[cfg(windows)]
mod platform {
    use windows_sys::Win32::Foundation::{
        CloseHandle, GetLastError, ERROR_ALREADY_EXISTS, ERROR_FILE_NOT_FOUND, HANDLE,
    };
    use windows_sys::Win32::System::Threading::{
        CreateMutexW, OpenMutexW, SYNCHRONIZATION_SYNCHRONIZE,
    };
    use windows_sys::Win32::UI::WindowsAndMessaging::AllowSetForegroundWindow;

    const MUTEX_NAME: &str = "Local\\KlipperFarmClient-v1.14.5";

    pub enum Acquire {
        Owned(Guard),
        AlreadyRunning,
    }

    pub struct Guard {
        handle: isize,
    }

    pub fn acquire() -> Result<Acquire, String> {
        let name: Vec<u16> = MUTEX_NAME.encode_utf16().chain(Some(0)).collect();
        // SAFETY: name is NUL-terminated and lives for the duration of the call.
        let handle = unsafe { CreateMutexW(std::ptr::null(), 0, name.as_ptr()) };
        if handle.is_null() {
            // SAFETY: GetLastError has no preconditions.
            let error = unsafe { GetLastError() };
            return Err(format!("Не удалось создать Windows named mutex: {error}"));
        }
        // SAFETY: GetLastError immediately follows CreateMutexW as required by Win32.
        if unsafe { GetLastError() } == ERROR_ALREADY_EXISTS {
            // SAFETY: handle was returned successfully by CreateMutexW.
            unsafe { CloseHandle(handle) };
            return Ok(Acquire::AlreadyRunning);
        }
        Ok(Acquire::Owned(Guard {
            handle: handle as isize,
        }))
    }

    pub fn owner_present() -> bool {
        let name: Vec<u16> = MUTEX_NAME.encode_utf16().chain(Some(0)).collect();
        // SAFETY: the name is NUL-terminated and this probe never takes mutex
        // ownership. Unavailable permissions are treated as an existing owner.
        let handle = unsafe { OpenMutexW(SYNCHRONIZATION_SYNCHRONIZE, 0, name.as_ptr()) };
        if handle.is_null() {
            // SAFETY: GetLastError immediately follows the failed Win32 call.
            return unsafe { GetLastError() } != ERROR_FILE_NOT_FOUND;
        }
        // SAFETY: the successfully opened probe handle is closed exactly once.
        unsafe { CloseHandle(handle) };
        true
    }

    pub fn allow_foreground(pid: u32) {
        // SAFETY: this only grants the already-running lease owner's PID the
        // foreground permission held by this user-initiated secondary launch.
        // ASFW_ANY is deliberately never used.
        unsafe { AllowSetForegroundWindow(pid) };
    }

    impl Drop for Guard {
        fn drop(&mut self) {
            // SAFETY: this handle is owned by Guard and closed exactly once.
            unsafe { CloseHandle(self.handle as HANDLE) };
        }
    }
}

#[cfg(not(windows))]
mod platform {
    pub enum Acquire {
        Owned(Guard),
        #[allow(dead_code)]
        AlreadyRunning,
    }

    pub struct Guard;

    pub fn allow_foreground(_pid: u32) {}

    pub fn owner_present() -> bool {
        true
    }

    pub fn acquire() -> Result<Acquire, String> {
        Ok(Acquire::Owned(Guard))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn v17_lease_requires_a_valid_port_and_token() {
        let record =
            parse_lease_record("pid=42\nport=49152\ntoken=00112233445566778899aabbccddeeff\n")
                .unwrap();
        assert_eq!(record.pid, Some(42));
        assert_eq!(record.port, 49_152);
        assert_eq!(
            record.token.as_deref(),
            Some("00112233445566778899aabbccddeeff")
        );
        assert!(parse_lease_record("port=0\ntoken=bad").is_err());
        assert!(parse_lease_record("pid=0\nport=49152").is_err());
        assert!(parse_lease_record("pid=not-a-pid\nport=49152").is_err());
    }

    #[test]
    fn legacy_fixed_port_lease_remains_compatible() {
        let record = parse_lease_record("pid=42\nport=45873\n").unwrap();
        assert_eq!(record.port, 45_873);
        assert!(record.token.is_none());
    }

    const TEST_TOKEN: &str = "00112233445566778899aabbccddeeff";

    fn test_lease_path(label: &str) -> PathBuf {
        static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        std::env::temp_dir().join(format!(
            "kf-instance-{label}-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ))
    }

    fn publish_test_lease(path: &Path, listener: &TcpListener) {
        fs::write(
            path,
            format!(
                "port={}\ntoken={TEST_TOKEN}\n",
                listener.local_addr().unwrap().port()
            ),
        )
        .unwrap();
    }

    fn accept_test_focus(listener: TcpListener) -> TcpStream {
        let (mut stream, _) = listener.accept().unwrap();
        stream.set_read_timeout(Some(Duration::from_secs(3))).unwrap();
        let expected = focus_message(TEST_TOKEN);
        let mut message = vec![0; expected.len()];
        stream.read_exact(&mut message).unwrap();
        assert_eq!(message, expected, "focus transport lost its secret token");
        stream
    }

    #[test]
    fn instance_focus_waits_for_mutex_lease_publication() {
        let path = test_lease_path("publication");
        let server_path = path.clone();
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let server = thread::spawn(move || {
            thread::sleep(Duration::from_millis(250));
            publish_test_lease(&server_path, &listener);
            accept_test_focus(listener).write_all(FOCUS_ACK).unwrap();
        });
        assert!(signal_existing_with_deadline(
            &path,
            Duration::from_secs(2),
            || true
        ));
        server.join().unwrap();
        fs::remove_file(path).unwrap();
    }

    #[test]
    fn instance_focus_waits_past_old_half_second_ack_limit() {
        let path = test_lease_path("delayed-ack");
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        publish_test_lease(&path, &listener);
        let server = thread::spawn(move || {
            let mut stream = accept_test_focus(listener);
            thread::sleep(Duration::from_millis(700));
            stream.write_all(FOCUS_ACK).unwrap();
        });
        assert!(signal_existing_with_deadline(
            &path,
            Duration::from_secs(2),
            || true
        ));
        server.join().unwrap();
        fs::remove_file(path).unwrap();
    }

    #[test]
    fn instance_focus_never_accepts_an_unconfirmed_ack() {
        let path = test_lease_path("invalid-ack");
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        publish_test_lease(&path, &listener);
        let server = thread::spawn(move || {
            accept_test_focus(listener)
                .write_all(&[b'X'; FOCUS_ACK.len()])
                .unwrap();
        });
        assert!(!signal_existing_with_deadline(
            &path,
            Duration::from_millis(300),
            || true
        ));
        server.join().unwrap();
        fs::remove_file(path).unwrap();
    }

    #[test]
    fn instance_focus_ack_has_an_absolute_deadline() {
        let path = test_lease_path("trickled-ack");
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        publish_test_lease(&path, &listener);
        let server = thread::spawn(move || {
            let mut stream = accept_test_focus(listener);
            for byte in FOCUS_ACK {
                if stream.write_all(&[*byte]).is_err() {
                    break;
                }
                thread::sleep(Duration::from_millis(90));
            }
        });
        let started = Instant::now();
        assert!(!signal_existing_with_deadline(
            &path,
            Duration::from_millis(250),
            || true
        ));
        assert!(started.elapsed() < Duration::from_secs(1));
        server.join().unwrap();
        fs::remove_file(path).unwrap();
    }

    #[test]
    fn instance_focus_stops_waiting_when_mutex_owner_exits() {
        let path = test_lease_path("owner-exited");
        let started = Instant::now();
        assert!(!signal_existing_with_deadline(
            &path,
            Duration::from_secs(30),
            || false
        ));
        assert!(started.elapsed() < Duration::from_millis(250));
    }

    #[test]
    fn instance_focus_missing_lease_has_a_bounded_startup_grace() {
        let path = test_lease_path("missing");
        let started = Instant::now();
        assert!(!signal_existing_with_deadline(
            &path,
            Duration::from_millis(250),
            || true
        ));
        assert!(started.elapsed() >= Duration::from_millis(200));
        assert!(started.elapsed() < Duration::from_secs(1));
    }

    #[test]
    fn instance_focus_normal_first_launch_does_not_wait_for_a_lease() {
        let path = test_lease_path("first-launch");
        let started = Instant::now();
        assert!(!signal_existing_with_retry(&path));
        assert!(started.elapsed() < Duration::from_millis(250));
    }

    #[test]
    fn instance_focus_refused_stale_lease_does_not_wait_for_startup_grace() {
        let path = test_lease_path("stale");
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        publish_test_lease(&path, &listener);
        drop(listener);
        let started = Instant::now();
        assert!(!signal_existing_with_retry(&path));
        assert!(started.elapsed() < Duration::from_secs(3));
        fs::remove_file(path).unwrap();
    }

}

